<script setup>
import { reactive, watch } from "vue";
const props = defineProps({ type: { type: String, required: true }, item: { type: Object, default: null }, loading: Boolean, error: { type: String, default: "" } });
const emit = defineEmits(["submit", "cancel"]); const form = reactive({ name: "" });
watch(() => props.item, (item) => { form.name = item?.name || ""; }, { immediate: true });
const label = () => props.type === "department" ? "département" : "secteur";
function submit() { emit("submit", { name: form.name.trim() }); }
</script>
<template><section class="form-page"><button type="button" class="back-link" @click="$emit('cancel')">← Retour à la liste</button><div class="page-intro"><p class="eyebrow">Administration / Référentiels</p><h2>{{ item ? "Modifier" : "Créer" }} un {{ label() }}</h2><p>Un nom clair permet de retrouver rapidement les doléances concernées.</p></div><form class="form-card" @submit.prevent="submit"><div v-if="error" class="alert">{{ error }}</div><label>Nom<input v-model.trim="form.name" required maxlength="120" :placeholder="`Ex. ${label()}`" autofocus /></label><div class="form-actions"><button type="button" class="secondary-button" @click="$emit('cancel')">Annuler</button><button class="primary-button" :disabled="loading">{{ loading ? "Enregistrement…" : "Enregistrer" }}</button></div></form></section></template>
<style scoped>.form-page{max-width:900px;margin:0 auto}.back-link{padding:0;border:0;color:#7186ae;background:none;font-size:.72rem;font-weight:700;cursor:pointer}.page-intro{margin:1.6rem 0}.eyebrow{margin:0 0 .55rem;color:#6d91e4;font-size:.68rem;font-weight:800;letter-spacing:.15em;text-transform:uppercase}.page-intro h2{margin:0;color:#1c2d46;font-size:2rem;letter-spacing:-.06em}.page-intro p:last-child{margin:.6rem 0 0;color:#8b99ab;font-size:.8rem}.form-card{max-width:680px;padding:1.4rem;border:1px solid #e8eef6;border-radius:.9rem;background:#fff;box-shadow:0 5px 15px rgb(30 52 84 / 3%)}.form-card label{display:grid;gap:.45rem;color:#53647c;font-size:.72rem;font-weight:700}.form-card input{width:100%;padding:.75rem;border:1px solid #dce4ef;border-radius:.5rem;outline:0;color:#30415a;font-size:.8rem}.form-card input:focus{border-color:#6d95eb;box-shadow:0 0 0 4px rgb(79 120 232 / 10%)}.form-actions{display:flex;justify-content:flex-end;gap:.6rem;margin-top:1.3rem}.primary-button,.secondary-button{padding:.72rem 1rem;border:0;border-radius:.5rem;font-size:.72rem;font-weight:700;cursor:pointer}.primary-button{color:#fff;background:#4776da}.primary-button:disabled{opacity:.6}.secondary-button{color:#68788e;background:#f1f4f8}.alert{margin-bottom:1rem;padding:.7rem;border:1px solid #ffd7db;border-radius:.5rem;color:#b33e4b;background:#fff3f4;font-size:.75rem}@media(max-width:600px){.form-actions{flex-direction:column-reverse}.form-actions button{width:100%}}
</style>
